class GitHub:
    """Small stdlib-only wrapper around ``gh``."""

    def __init__(
        self,
        *,
        repo_root: Path | None = None,
        gh: Path | None = None,
        repo: str | None = None,
    ) -> None:
        self.repo_root = (repo_root or Path.cwd()).resolve()
        self.gh = gh or discover_gh()
        self.repo = repo or discover_repository(self.repo_root)
        self.owner, self.name = self.repo.split("/", 1)
        self.retries = max(0, int(os.environ.get("MIPSTARRE_GH_RETRIES", "3")))
        self.retry_delay = max(
            0.0, float(os.environ.get("MIPSTARRE_GH_RETRY_DELAY", "1"))
        )
        self.timeout = max(1.0, float(os.environ.get("MIPSTARRE_GH_TIMEOUT", "60")))

    def run(
        self,
        arguments: Sequence[str],
        *,
        input_text: str | None = None,
        retry: bool = False,
    ) -> CommandResult:
        attempts = self.retries + 1 if retry else 1
        last: GitHubError | None = None
        for attempt in range(attempts):
            try:
                result = subprocess.run(
                    [str(self.gh), *arguments],
                    cwd=str(self.repo_root),
                    input=input_text,
                    text=True,
                    capture_output=True,
                    timeout=self.timeout,
                    check=False,
                )
            except subprocess.TimeoutExpired as exc:
                last = GitHubError(
                    f"gh command timed out after {self.timeout:g}s",
                    transient=True,
                    stdout=_safe_text(exc.stdout),
                )
            except OSError as exc:
                last = GitHubError(f"cannot execute gh: {_safe_text(str(exc))}")
            else:
                if result.returncode == 0:
                    return CommandResult(result.stdout, result.stderr)
                stderr = _safe_text(result.stderr or result.stdout)
                status = _status_from_stderr(stderr)
                last = GitHubError(
                    f"GitHub operation failed: {stderr or 'gh exited nonzero'}",
                    status=status,
                    transient=_is_transient(stderr, status),
                    stdout=_safe_text(result.stdout),
                )
            assert last is not None
            if not retry or not last.transient or attempt + 1 >= attempts:
                raise last
            time.sleep(self.retry_delay * (2**attempt))
        raise last or GitHubError("GitHub operation failed")

    def api(
        self,
        endpoint: str,
        *,
        method: str = "GET",
        data: Any | None = None,
        retry: bool | None = None,
    ) -> Any:
        arguments = [
            "api",
            "--method",
            method,
            endpoint.lstrip("/"),
            "-H",
            f"Accept: {ACCEPT}",
            "-H",
            f"X-GitHub-Api-Version: {API_VERSION}",
        ]
        input_text = None
        if data is not None:
            arguments.extend(["-H", "Content-Type: application/json", "--input", "-"])
            input_text = json.dumps(data, ensure_ascii=False)
        if retry is None:
            retry = method.upper() == "GET"
        result = self.run(arguments, input_text=input_text, retry=retry)
        if not result.stdout.strip():
            return None
        try:
            return json.loads(result.stdout)
        except json.JSONDecodeError as exc:
            raise GitHubError(
                f"gh returned invalid JSON for {method} {endpoint}: {exc}"
            ) from exc

    def paginate(self, endpoint: str, *, item_key: str | None = None) -> list[dict[str, Any]]:
        parsed = urllib.parse.urlsplit(endpoint)
        query = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
        query = [(key, value) for key, value in query if key not in {"page", "per_page"}]
        collected: list[dict[str, Any]] = []
        for page in range(1, 101):
            page_query = urllib.parse.urlencode([*query, ("per_page", "100"), ("page", str(page))])
            page_endpoint = urllib.parse.urlunsplit(
                (parsed.scheme, parsed.netloc, parsed.path, page_query, parsed.fragment)
            )
            payload = self.api(page_endpoint)
            if item_key is not None:
                if not isinstance(payload, dict) or not isinstance(payload.get(item_key), list):
                    raise GitHubError(
                        f"paginated endpoint {endpoint} did not return list key {item_key!r}"
                    )
                items = payload[item_key]
            else:
                items = payload
            if not isinstance(items, list):
                raise GitHubError(f"paginated endpoint {endpoint} did not return a JSON list")
            if not all(isinstance(item, dict) for item in items):
                raise GitHubError(f"paginated endpoint {endpoint} returned a non-object item")
            collected.extend(items)
            if len(items) < 100:
                return collected
        raise GitHubError(f"pagination exceeded 100 pages for {endpoint}")

    def probe_authentication(self) -> dict[str, Any]:
        try:
            payload = self.api(f"/repos/{self.repo}")
        except GitHubError as exc:
            raise GitHubError(
                "GitHub authentication/capability probe failed for the configured "
                f"repository {self.repo}: {exc}. Run 'gh auth login' or set the "
                "credential expected by gh; no local fallback was created.",
                status=exc.status,
                transient=exc.transient,
            ) from exc
        if not isinstance(payload, dict):
            raise GitHubError("authentication probe returned a non-object response")
        return payload

    def get_issue(self, number: int) -> dict[str, Any]:
        payload = self.api(f"/repos/{self.repo}/issues/{number}")
        if not isinstance(payload, dict):
            raise GitHubError(f"issue #{number} response is not a JSON object")
        return payload

    def get_pull(self, number: int) -> dict[str, Any]:
        payload = self.api(f"/repos/{self.repo}/pulls/{number}")
        if not isinstance(payload, dict):
            raise GitHubError(f"pull request #{number} response is not a JSON object")
        return payload

    def labels(self) -> list[dict[str, Any]]:
        return self.paginate(f"/repos/{self.repo}/labels")

    def validate_labels(self, requested: Iterable[str]) -> list[str]:
        labels = list(dict.fromkeys(name.strip() for name in requested if name.strip()))
        if not labels:
            return []
        existing = {str(item.get("name")) for item in self.labels()}
        missing = [name for name in labels if name not in existing]
        if missing:
            raise GitHubError(
                "GitHub label(s) do not exist in "
                f"{self.repo}: {', '.join(missing)}. Repository labels are authoritative."
            )
        return labels

    def remove_label(self, number: int, label: str) -> None:
        encoded = urllib.parse.quote(label, safe="")

        def present() -> bool:
            issue = self.get_issue(number)
            names = {
                str(item.get("name") if isinstance(item, dict) else item)
                for item in (issue.get("labels") or [])
            }
            return label in names

        if not present():
            return
        last: GitHubError | None = None
        for attempt in range(self.retries + 1):
            try:
                self.api(
                    f"/repos/{self.repo}/issues/{number}/labels/{encoded}",
                    method="DELETE",
                    retry=False,
                )
                return
            except GitHubError as exc:
                last = exc
                if not present():
                    return
                if not exc.transient or attempt >= self.retries:
                    raise
                time.sleep(self.retry_delay * (2**attempt))
        raise last or GitHubError("label removal failed")

    def comments(self, number: int) -> list[dict[str, Any]]:
        return self.paginate(f"/repos/{self.repo}/issues/{number}/comments")

    def reviews(self, number: int) -> list[dict[str, Any]]:
        return self.paginate(f"/repos/{self.repo}/pulls/{number}/reviews")

    def pull_commits(self, number: int) -> list[dict[str, Any]]:
        pull = self.get_pull(number)
        expected = pull.get("commits")
        if not isinstance(expected, int) or expected < 0:
            raise GitHubError(
                f"PR #{number} does not report a trustworthy commit count"
            )
        if expected > 250:
            raise GitHubError(
                f"PR #{number} reports {expected} commits, beyond GitHub's "
                "250-commit PR endpoint cap; complete fix history cannot be proven"
            )
        rows = self.paginate(f"/repos/{self.repo}/pulls/{number}/commits")
        if len(rows) != expected:
            raise GitHubError(
                f"PR #{number} reports {expected} commits but the endpoint returned "
                f"{len(rows)}; refusing incomplete history"
            )
        return rows

    def statuses(self, sha: str) -> list[dict[str, Any]]:
        sha = normalize_sha(sha)
        return self.paginate(f"/repos/{self.repo}/commits/{sha}/statuses")

    def latest_statuses(self, sha: str) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        rows = self.statuses(sha)
        rows.sort(key=lambda row: (str(row.get("created_at") or ""), int(row.get("id") or 0)), reverse=True)
        for row in rows:
            context = str(row.get("context") or "").casefold()
            if context and context not in result:
                result[context] = row
        return result

    @staticmethod
    def _latest(rows: Iterable[dict[str, Any]], timestamp: str) -> dict[str, Any]:
        candidates = list(rows)
        if not candidates:
            raise GitHubError("no matching authoritative publication was found")
        candidates.sort(
            key=lambda row: (
                str(row.get(timestamp) or row.get("created_at") or ""),
                int(row.get("id") or 0),
            ),
            reverse=True,
        )
        return candidates[0]

    def ci_manifest(self, number: int, sha: str) -> tuple[dict[str, Any], dict[str, Any]]:
        sha = normalize_sha(sha)
        matches: list[dict[str, Any]] = []
        for row in self.comments(number):
            body = str(row.get("body") or "")
            markers = _CI_MARKER_RE.findall(body)
            if not any(int(pr) == number and head.lower() == sha for pr, head, _ in markers):
                continue
            matches.append(row)
        row = self._latest(matches, "created_at")
        body = str(row.get("body") or "")
        fenced = re.search(r"```json\s*\n(.*?)\n```", body, re.DOTALL)
        if not fenced:
            raise GitHubError("latest exact-head CI comment has no JSON manifest fence")
        try:
            manifest = json.loads(fenced.group(1))
        except json.JSONDecodeError as exc:
            raise GitHubError(f"latest exact-head CI manifest is invalid JSON: {exc}") from exc
        if not isinstance(manifest, dict):
            raise GitHubError("latest exact-head CI manifest is not an object")
        if str(manifest.get("head_sha") or "").lower() != sha:
            raise GitHubError("latest CI manifest does not record the exact requested head")
        if str(manifest.get("pr") or "") != str(number) or manifest.get("partial"):
            raise GitHubError("latest CI manifest has the wrong PR or is partial")
        steps = manifest.get("steps")
        if not isinstance(steps, list):
            raise GitHubError("latest CI manifest has no step list")
        names = {str(step.get("step") or "") for step in steps if isinstance(step, dict)}
        if names != set(CANONICAL_CI_STEPS):
            raise GitHubError("latest CI manifest does not contain exactly the canonical steps")
        return row, manifest

    def review_ledger(self, number: int, sha: str) -> dict[str, Any]:
        sha = normalize_sha(sha)
        matches: list[dict[str, Any]] = []
        for row in self.reviews(number):
            body = str(row.get("body") or "")
            markers = _REVIEW_MARKER_RE.findall(body)
            if not any(int(pr) == number and head.lower() == sha for pr, head, _ in markers):
                continue
            if str(row.get("commit_id") or "").lower() != sha:
                raise GitHubError("review ledger marker is bound to a different commit")
            matches.append(row)
        row = self._latest(matches, "submitted_at")
        body = str(row.get("body") or "")
        if body.count("<!-- mipstarre:review-ledger ") != 1:
            raise GitHubError("latest exact-head review ledger has ambiguous markers")
        return row

    def post_status(self, sha: str, context: str, state: str, description: str) -> None:
        sha = normalize_sha(sha)
        context = context.strip()
        if not context or any(ord(ch) < 32 for ch in context):
            raise GitHubError("commit status context must be nonempty and printable")
        if state not in {"pending", "success", "failure", "error"}:
            raise GitHubError(f"invalid commit status state {state!r}")
        digest = stable_digest(
            {
                "sha": sha,
                "context": context.casefold(),
                "state": state,
                "description": description,
            },
            length=16,
        )
        suffix = f" [mip:{digest}]"
        rendered_description = description[: 140 - len(suffix)].rstrip() + suffix

        def lookup() -> dict[str, Any] | None:
            for row in self.statuses(sha):
                row_sha = str(row.get("sha") or "")
                if not _SHA_RE.fullmatch(row_sha) or row_sha.lower() != sha:
                    continue
                if str(row.get("context") or "").casefold() != context.casefold():
                    continue
                if str(row.get("state") or "").casefold() != state:
                    continue
                if str(row.get("description") or "") == rendered_description:
                    return row
            return None

        def mutate() -> dict[str, Any]:
            payload = self.api(
                f"/repos/{self.repo}/statuses/{sha}",
                method="POST",
                data={
                    "state": state,
                    "context": context,
                    "description": rendered_description,
                },
                retry=False,
            )
            if not isinstance(payload, dict):
                raise GitHubError("commit status creation returned a non-object response")

#!/usr/bin/env python3
"""Merge a GitHub pull request after all exact-head local gates pass."""

from __future__ import annotations

import argparse
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any, Sequence

sys.path.insert(0, str(Path(__file__).resolve().parent))
from github_api import (  # noqa: E402
    ADJUDICATION_LABEL,
    CANONICAL_CI_CONTEXTS,
    REVIEW_CONTEXT,
    GitHub,
    GitHubError,
    fix_iteration_count,
    normalize_number,
    normalize_sha,
    pull_head,
)


DEFAULT_FIX_CAP = 5
UNRESOLVED_RE = re.compile(r"^\s*[-*]\s*\[ \]\s+F\d+", re.MULTILINE)
DISPOSITION_RE = re.compile(r"^Disposition:\s*\S.*$", re.MULTILINE)


class GateFailure(RuntimeError):
    """A merge-gate refusal with an operator-facing explanation."""


def git(root: Path, *arguments: str, check: bool = True) -> str:
    result = subprocess.run(
        ["git", "-C", str(root), *arguments],
        text=True,
        capture_output=True,
        check=False,
    )
    if check and result.returncode != 0:
        raise GateFailure(
            result.stderr.strip() or f"git {' '.join(arguments)} failed"
        )
    return result.stdout.strip()


def primary_root(value: Path | None) -> Path:
    root = (value or Path.cwd()).resolve()
    common = git(root, "rev-parse", "--path-format=absolute", "--git-common-dir")
    common_path = Path(common)
    return common_path.parent if common_path.name == ".git" else root


def branch_worktree(root: Path, branch: str) -> Path | None:
    current: Path | None = None
    for line in git(root, "worktree", "list", "--porcelain").splitlines():
        if line.startswith("worktree "):
            current = Path(line.removeprefix("worktree "))
        elif line == f"branch refs/heads/{branch}" and current is not None:
            return current
    return None


def exact_local_head(root: Path, branch: str) -> tuple[str, Path]:
    if any(ch in branch for ch in "[]~^:?*\\ \t\r\n"):
        raise GateFailure(f"unsafe GitHub head branch {branch!r}")
    worktree = branch_worktree(root, branch)
    if worktree is None or not worktree.is_dir():
        raise GateFailure(f"no local worktree is registered for PR branch {branch!r}")
    symbolic = git(worktree, "symbolic-ref", "--quiet", "--short", "HEAD")
    if symbolic != branch:
        raise GateFailure(
            f"worktree {worktree} is on {symbolic!r}, expected {branch!r}"
        )
    return normalize_sha(git(worktree, "rev-parse", "HEAD")), worktree


def require_open_mergeable(pull: dict[str, Any], number: int) -> tuple[str, str, str]:
    if str(pull.get("state") or "").casefold() != "open":
        raise GateFailure(f"PR #{number} is not open")
    if bool(pull.get("draft")):
        raise GateFailure(f"PR #{number} is a draft")
    if pull.get("mergeable") is not True:
        state = pull.get("mergeable_state") or "unknown"
        raise GateFailure(f"PR #{number} is not proven mergeable (state={state})")
    return pull_head(pull)


def require_statuses(client: GitHub, sha: str) -> dict[str, dict[str, Any]]:
    latest = client.latest_statuses(sha)
    failures: list[str] = []
    for context in CANONICAL_CI_CONTEXTS:
        state = str(
            (latest.get(context.casefold()) or {}).get("state") or "missing"
        ).casefold()
        if state != "success":
            failures.append(f"{context}={state}")
    if failures:
        raise GateFailure("exact-head CI gate failed: " + ", ".join(failures))
    return latest


def row_order(row: dict[str, Any]) -> tuple[str, int]:
    return (
        str(row.get("submitted_at") or row.get("created_at") or ""),
        int(row.get("id") or 0),
    )


def require_review(client: GitHub, number: int, sha: str) -> None:
    latest = client.latest_statuses(sha)
    summary = latest.get(REVIEW_CONTEXT.casefold()) or {}
    if str(summary.get("state") or "").casefold() != "success":
        raise GateFailure(
            f"{REVIEW_CONTEXT} is not successful on exact head {sha}"
        )
    try:
        ledger = client.review_ledger(number, sha)
    except GitHubError as exc:
        raise GateFailure(f"no valid exact-head review ledger: {exc}") from exc
    body = str(ledger.get("body") or "")
    if UNRESOLVED_RE.search(body):
        raise GateFailure("the latest exact-head review ledger has unresolved findings")
    ledger_order = row_order(ledger)
    for review in client.reviews(number):
        if str(review.get("commit_id") or "").lower() != sha:
            continue
        if str(review.get("state") or "").upper() != "CHANGES_REQUESTED":
            continue
        if row_order(review) > ledger_order:
            raise GateFailure("a later exact-head CHANGES_REQUESTED review is unresolved")


def require_adjudication(
    client: GitHub, pull: dict[str, Any], number: int, sha: str
) -> None:
    labels = {
        str(item.get("name") if isinstance(item, dict) else item)
        for item in (pull.get("labels") or [])
    }
    if ADJUDICATION_LABEL not in labels:
        raise GateFailure(f"adjudicated merge requires label {ADJUDICATION_LABEL!r}")
    marker = f"<!-- mipstarre:adjudication pr={number} head={sha} -->"
    matches: list[dict[str, Any]] = []
    for row in client.comments(number):
        body = str(row.get("body") or "")
        if body.startswith("ADJUDICATION") and marker in body:
            matches.append(row)
    if not matches:
        raise GateFailure("no current-head ADJUDICATION comment with a stable marker")
    matches.sort(key=row_order, reverse=True)
    body = str(matches[0].get("body") or "")
    if body.count(marker) != 1 or not DISPOSITION_RE.search(body):
        raise GateFailure(
            "the adjudication comment must contain one exact-head marker and a "
            "nonempty 'Disposition:' line"
        )


def require_no_live_fix(cache: Path, branch: str) -> None:
    lock = cache / "locks" / f"fix-{branch.replace('/', '-')}.lock"
    if not lock.is_dir():
        return
    try:
        pid = int((lock / "pid").read_text(encoding="utf-8").strip())
    except (OSError, ValueError):
        return
    try:
        os.kill(pid, 0)
    except OSError:
        return
    raise GateFailure(f"live auto-fix lock {lock} is held by pid {pid}")


def require_merge_capability(client: GitHub) -> None:
    result = client.run(["pr", "merge", "--help"], retry=False)
    if "--match-head-commit" not in result.stdout:
        raise GateFailure(
            "installed gh lacks 'pr merge --match-head-commit'; upgrade before merging"
        )


def recheck_head(
    client: GitHub, number: int, expected: str, root: Path, branch: str
) -> dict[str, Any]:
    pull = client.get_pull(number)
    _, _, remote = pull_head(pull)
    local, _ = exact_local_head(root, branch)
    if remote != expected or local != expected:
        raise GateFailure(
            f"head moved during gate evaluation (expected={expected}, "
            f"remote={remote}, local={local})"
        )
    return pull


def fast_forward_base(root: Path, base: str) -> None:
    git(
        root,
        "fetch",
        "--no-tags",
        "github",
        f"refs/heads/{base}:refs/remotes/github/{base}",
    )
    worktree = branch_worktree(root, base)
    if worktree is None:
        raise GateFailure(
            f"GitHub merged the PR, but no local checkout of base branch {base!r} exists"
        )
    if git(worktree, "status", "--porcelain"):
        raise GateFailure(
            f"GitHub merged the PR, but base worktree {worktree} is dirty; "
            "it was not advanced"
        )
    git(worktree, "merge", "--ff-only", f"refs/remotes/github/{base}")


def cleanup_feature(root: Path, branch: str, worktree: Path, merge_sha: str) -> None:
    if git(worktree, "status", "--porcelain"):
        raise GateFailure(
            f"PR merged, but feature worktree {worktree} is dirty; cleanup was skipped"
        )
    ancestor = subprocess.run(
        ["git", "-C", str(root), "merge-base", "--is-ancestor", branch, merge_sha],
        check=False,
    )
    if ancestor.returncode != 0:
        raise GateFailure(
            f"PR merged, but local branch {branch!r} is not contained in {merge_sha}; "
            "cleanup was skipped"
        )
    git(root, "worktree", "remove", str(worktree))
    git(root, "branch", "-d", branch)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("number", help="GitHub pull-request number")
    parser.add_argument("--adjudicated", action="store_true")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--fix-cap", type=int, default=None)
    parser.add_argument("--repo-root", type=Path)
    return parser


def run(args: argparse.Namespace) -> int:
    number = normalize_number(args.number, kind="PR number")
    root = primary_root(args.repo_root)
    cache = Path(
        os.environ.get("MIPSTARRE_CACHE_ROOT", Path.home() / ".cache/mipstarre-dev")
    )
    cap = args.fix_cap
    if cap is None:
        cap = int(os.environ.get("MIPSTARRE_FIX_CAP", str(DEFAULT_FIX_CAP)))
    if cap < 0:
        raise GateFailure("fix cap must be nonnegative")

#!/usr/bin/env python3
"""Shared GitHub access for the local workflow.

GitHub is the sole authority for active issues and pull requests.  This module
centralizes CLI and repository discovery, the functional authentication probe,
REST headers, JSON handling, pagination, bounded retries, and idempotent
publication markers.  It deliberately has no offline mutation path.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
import urllib.parse
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Iterable, Sequence, TypeVar


API_VERSION = "2022-11-28"
ACCEPT = "application/vnd.github+json"
DOCUMENTED_REPOSITORY = "Dengnifer/MIPStarRE-A"
CANONICAL_CI_STEPS = (
    "build",
    "blueprint-render",
    "paper-gaps",
    "blueprint-sync",
    "file-length",
    "proof-debt",
    "proof-evasion",
    "statement-origin",
)
CANONICAL_CI_CONTEXTS = tuple(f"local-ci/{step}" for step in CANONICAL_CI_STEPS)
REVIEW_CONTEXT = "local-review/summary"
AUTO_FIX_PREFIXES = ("[codex-auto-fix]", "[codex-review-fix]")
AUTO_FIX_LABEL = "auto-fix-codex"
ADJUDICATION_LABEL = "adjudicated"

_CI_MARKER_RE = re.compile(
    r"<!-- mipstarre:ci-manifest pr=(\d+) "
    r"head=((?:[0-9a-fA-F]{40}|[0-9a-fA-F]{64})) run=([^<>\s]+) -->"
)
_REVIEW_MARKER_RE = re.compile(
    r"<!-- mipstarre:review-ledger pr=(\d+) "
    r"head=((?:[0-9a-fA-F]{40}|[0-9a-fA-F]{64})) run=([^<>\s]+) -->"
)

_REPO_RE = re.compile(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$")
_HTTP_RE = re.compile(r"(?:HTTP|status(?: code)?)\D*(\d{3})", re.IGNORECASE)
_TRANSIENT_TEXT = (
    "connection reset",
    "connection refused",
    "connection timed out",
    "context deadline exceeded",
    "could not resolve host",
    "dial tcp",
    "eof",
    "network is unreachable",
    "service unavailable",
    "temporary failure",
    "timeout",
    "timed out",
    "tls handshake timeout",
)
_RATE_LIMIT_TEXT = (
    "api rate limit exceeded",
    "rate limit exceeded",
    "secondary rate limit",
    "retry-after",
    "retry after",
)
_MARKER_RE = re.compile(r"^<!-- mipstarre:[a-z0-9-]+(?: [^<>\r\n]+)* -->$")
_SHA_RE = re.compile(r"(?:[0-9a-fA-F]{40}|[0-9a-fA-F]{64})")


class GitHubError(RuntimeError):
    """A safe, classified GitHub operation failure."""

    def __init__(
        self,
        message: str,
        *,
        status: int | None = None,
        transient: bool = False,
        stdout: str = "",
    ) -> None:
        super().__init__(message)
        self.status = status
        self.transient = transient
        self.stdout = stdout


@dataclass(frozen=True)
class CommandResult:
    stdout: str
    stderr: str


T = TypeVar("T")


def _safe_text(text: str | bytes | None) -> str:
    """Strip controls and redact token-valued environment variables."""
    if text is None:
        text = ""
    if isinstance(text, bytes):
        text = text.decode("utf-8", errors="replace")
    clean = "".join(ch for ch in text if ch in "\n\t" or ord(ch) >= 32)
    for name, value in os.environ.items():
        if "TOKEN" in name.upper() and value:
            clean = clean.replace(value, "<redacted>")
    return clean.strip()[:2000]


def _status_from_stderr(stderr: str) -> int | None:
    match = _HTTP_RE.search(stderr)
    if match:
        return int(match.group(1))
    match = re.search(r"\b(4\d\d|5\d\d)\b", stderr)
    return int(match.group(1)) if match else None


def _is_transient(stderr: str, status: int | None) -> bool:
    if status == 429 or (status is not None and 500 <= status <= 599):
        return True
    lowered = stderr.lower()
    if status == 403 and any(fragment in lowered for fragment in _RATE_LIMIT_TEXT):
        return True
    return any(fragment in lowered for fragment in _TRANSIENT_TEXT)


def stable_digest(payload: Any, *, length: int = 24) -> str:
    encoded = json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()[:length]


def stable_marker(kind: str, **parts: object) -> str:
    rendered = " ".join(f"{key}={value}" for key, value in parts.items())
    return f"<!-- mipstarre:{kind}{(' ' + rendered) if rendered else ''} -->"


def create_marker(kind: str, payload: Any) -> str:
    return stable_marker(f"{kind}-create", id=stable_digest(payload))


def normalize_number(value: str | int, *, kind: str = "number") -> int:
    text = str(value)
    if not re.fullmatch(r"[1-9]\d*", text):
        raise GitHubError(f"{kind} must be a positive GitHub number, got {text!r}")
    return int(text)


def normalize_sha(value: str, *, kind: str = "commit SHA") -> str:
    text = str(value).strip()
    if not _SHA_RE.fullmatch(text):
        raise GitHubError(f"{kind} must be an exact 40- or 64-hex SHA, got {text!r}")
    return text.lower()


def _validated_marker(marker: str, body: str) -> None:
    if not _MARKER_RE.fullmatch(marker):
        raise GitHubError(f"invalid or missing idempotency marker: {marker!r}")
    if body.count(marker) != 1:
        raise GitHubError("idempotent publication body must contain its marker exactly once")


def discover_gh() -> Path:
    override = os.environ.get("MIPSTARRE_GH")
    if override:
        path = Path(override).expanduser()
        if not path.is_file() or not os.access(path, os.X_OK):
            raise GitHubError(
                f"MIPSTARRE_GH points to a missing or non-executable file: {path}"
            )
        return path.resolve()
    found = shutil.which("gh")
    if found:
        return Path(found).resolve()
    user_local = Path.home() / ".local" / "bin" / "gh"
    if user_local.is_file() and os.access(user_local, os.X_OK):
        return user_local.resolve()
    raise GitHubError(
        "GitHub CLI not found. Set MIPSTARRE_GH, add gh to PATH, or install it "
        f"at {user_local}. No local fallback was created."
    )


def _repository_from_url(url: str) -> str | None:
    value = url.strip()
    patterns = (
        r"^(?:ssh://)?git@github\.com[:/]([^/]+/[^/]+?)(?:\.git)?$",
        r"^https?://github\.com/([^/]+/[^/]+?)(?:\.git)?/?$",
        r"^git://github\.com/([^/]+/[^/]+?)(?:\.git)?/?$",
    )
    for pattern in patterns:
        match = re.match(pattern, value)
        if match:
            return match.group(1).removesuffix(".git")
    return None


def discover_repository(repo_root: Path | None = None) -> str:
    override = os.environ.get("MIPSTARRE_GITHUB_REPO")
    if override:
        repo = override.strip().removesuffix(".git")
    else:
        root = repo_root or Path.cwd()
        result = subprocess.run(
            ["git", "-C", str(root), "remote", "get-url", "github"],
            text=True,
            capture_output=True,
            check=False,
        )
        repo = _repository_from_url(result.stdout) or ""
    if not _REPO_RE.fullmatch(repo):
        raise GitHubError(
            "cannot discover a GitHub owner/repository. Set "
            "MIPSTARRE_GITHUB_REPO or configure the 'github' remote; the "
            f"documented repository is {DOCUMENTED_REPOSITORY}."
        )
    return repo


class GitHub:
    """Small stdlib-only wrapper around ``gh``."""

    def __init__(
        self,
        *,
        repo_root: Path | None = None,
        gh: Path | None = None,
        repo: str | None = None,
    ) -> None:
        self.repo_root = (repo_root or Path.cwd()).resolve()
        self.gh = gh or discover_gh()
        self.repo = repo or discover_repository(self.repo_root)
        self.owner, self.name = self.repo.split("/", 1)
        self.retries = max(0, int(os.environ.get("MIPSTARRE_GH_RETRIES", "3")))
        self.retry_delay = max(
            0.0, float(os.environ.get("MIPSTARRE_GH_RETRY_DELAY", "1"))
        )
        self.timeout = max(1.0, float(os.environ.get("MIPSTARRE_GH_TIMEOUT", "60")))

    def run(
        self,
        arguments: Sequence[str],
        *,
        input_text: str | None = None,
        retry: bool = False,
    ) -> CommandResult:
        attempts = self.retries + 1 if retry else 1
        last: GitHubError | None = None
        for attempt in range(attempts):
            try:
                result = subprocess.run(
                    [str(self.gh), *arguments],
                    cwd=str(self.repo_root),
                    input=input_text,
                    text=True,
                    capture_output=True,
                    timeout=self.timeout,
                    check=False,
                )
            except subprocess.TimeoutExpired as exc:
                last = GitHubError(
                    f"gh command timed out after {self.timeout:g}s",
                    transient=True,
                    stdout=_safe_text(exc.stdout),
                )
            except OSError as exc:
                last = GitHubError(f"cannot execute gh: {_safe_text(str(exc))}")
            else:
                if result.returncode == 0:
                    return CommandResult(result.stdout, result.stderr)
                stderr = _safe_text(result.stderr or result.stdout)
                status = _status_from_stderr(stderr)
                last = GitHubError(
                    f"GitHub operation failed: {stderr or 'gh exited nonzero'}",
                    status=status,
                    transient=_is_transient(stderr, status),
                    stdout=_safe_text(result.stdout),
                )
            assert last is not None
            if not retry or not last.transient or attempt + 1 >= attempts:
                raise last
            time.sleep(self.retry_delay * (2**attempt))
        raise last or GitHubError("GitHub operation failed")

    def api(
        self,
        endpoint: str,
        *,
        method: str = "GET",
        data: Any | None = None,
        retry: bool | None = None,
    ) -> Any:
        arguments = [
            "api",
            "--method",
            method,
            endpoint.lstrip("/"),
            "-H",
            f"Accept: {ACCEPT}",
            "-H",
            f"X-GitHub-Api-Version: {API_VERSION}",
        ]
        input_text = None
        if data is not None:
            arguments.extend(["-H", "Content-Type: application/json", "--input", "-"])
            input_text = json.dumps(data, ensure_ascii=False)
        if retry is None:
            retry = method.upper() == "GET"
        result = self.run(arguments, input_text=input_text, retry=retry)
        if not result.stdout.strip():
            return None
        try:
            return json.loads(result.stdout)
        except json.JSONDecodeError as exc:
            raise GitHubError(
                f"gh returned invalid JSON for {method} {endpoint}: {exc}"
            ) from exc

    def paginate(self, endpoint: str, *, item_key: str | None = None) -> list[dict[str, Any]]:
        parsed = urllib.parse.urlsplit(endpoint)
        query = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
        query = [(key, value) for key, value in query if key not in {"page", "per_page"}]
        collected: list[dict[str, Any]] = []
        for page in range(1, 101):
            page_query = urllib.parse.urlencode([*query, ("per_page", "100"), ("page", str(page))])
            page_endpoint = urllib.parse.urlunsplit(
                (parsed.scheme, parsed.netloc, parsed.path, page_query, parsed.fragment)
            )
            payload = self.api(page_endpoint)
            if item_key is not None:
                if not isinstance(payload, dict) or not isinstance(payload.get(item_key), list):
                    raise GitHubError(
                        f"paginated endpoint {endpoint} did not return list key {item_key!r}"
                    )
                items = payload[item_key]
            else:
                items = payload
            if not isinstance(items, list):
                raise GitHubError(f"paginated endpoint {endpoint} did not return a JSON list")
            if not all(isinstance(item, dict) for item in items):
                raise GitHubError(f"paginated endpoint {endpoint} returned a non-object item")
            collected.extend(items)
            if len(items) < 100:
                return collected
        raise GitHubError(f"pagination exceeded 100 pages for {endpoint}")

    def probe_authentication(self) -> dict[str, Any]:
        try:
            payload = self.api(f"/repos/{self.repo}")
        except GitHubError as exc:
            raise GitHubError(
                "GitHub authentication/capability probe failed for the configured "
                f"repository {self.repo}: {exc}. Run 'gh auth login' or set the "
                "credential expected by gh; no local fallback was created.",
                status=exc.status,
                transient=exc.transient,
            ) from exc
        if not isinstance(payload, dict):
            raise GitHubError("authentication probe returned a non-object response")
        return payload

    def get_issue(self, number: int) -> dict[str, Any]:
        payload = self.api(f"/repos/{self.repo}/issues/{number}")
        if not isinstance(payload, dict):
            raise GitHubError(f"issue #{number} response is not a JSON object")
        return payload

    def get_pull(self, number: int) -> dict[str, Any]:
        payload = self.api(f"/repos/{self.repo}/pulls/{number}")
        if not isinstance(payload, dict):
            raise GitHubError(f"pull request #{number} response is not a JSON object")
        return payload

    def labels(self) -> list[dict[str, Any]]:
        return self.paginate(f"/repos/{self.repo}/labels")

    def validate_labels(self, requested: Iterable[str]) -> list[str]:
        labels = list(dict.fromkeys(name.strip() for name in requested if name.strip()))
        if not labels:
            return []
        existing = {str(item.get("name")) for item in self.labels()}
        missing = [name for name in labels if name not in existing]
        if missing:
            raise GitHubError(
                "GitHub label(s) do not exist in "
                f"{self.repo}: {', '.join(missing)}. Repository labels are authoritative."
            )
        return labels

    def remove_label(self, number: int, label: str) -> None:
        encoded = urllib.parse.quote(label, safe="")

        def present() -> bool:
            issue = self.get_issue(number)
            names = {
                str(item.get("name") if isinstance(item, dict) else item)
                for item in (issue.get("labels") or [])
            }
            return label in names

        if not present():
            return
        last: GitHubError | None = None
        for attempt in range(self.retries + 1):
            try:
                self.api(
                    f"/repos/{self.repo}/issues/{number}/labels/{encoded}",
                    method="DELETE",
                    retry=False,
                )
                return
            except GitHubError as exc:
                last = exc
                if not present():
                    return
                if not exc.transient or attempt >= self.retries:
                    raise
                time.sleep(self.retry_delay * (2**attempt))
        raise last or GitHubError("label removal failed")

    def comments(self, number: int) -> list[dict[str, Any]]:
        return self.paginate(f"/repos/{self.repo}/issues/{number}/comments")

    def reviews(self, number: int) -> list[dict[str, Any]]:
        return self.paginate(f"/repos/{self.repo}/pulls/{number}/reviews")

    def pull_commits(self, number: int) -> list[dict[str, Any]]:
        pull = self.get_pull(number)
        expected = pull.get("commits")
        if not isinstance(expected, int) or expected < 0:
            raise GitHubError(
                f"PR #{number} does not report a trustworthy commit count"
            )
        if expected > 250:
            raise GitHubError(
                f"PR #{number} reports {expected} commits, beyond GitHub's "
                "250-commit PR endpoint cap; complete fix history cannot be proven"
            )
        rows = self.paginate(f"/repos/{self.repo}/pulls/{number}/commits")
        if len(rows) != expected:
            raise GitHubError(
                f"PR #{number} reports {expected} commits but the endpoint returned "
                f"{len(rows)}; refusing incomplete history"
            )
        return rows

    def statuses(self, sha: str) -> list[dict[str, Any]]:
        sha = normalize_sha(sha)
        return self.paginate(f"/repos/{self.repo}/commits/{sha}/statuses")

    def latest_statuses(self, sha: str) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        rows = self.statuses(sha)
        rows.sort(key=lambda row: (str(row.get("created_at") or ""), int(row.get("id") or 0)), reverse=True)
        for row in rows:
            context = str(row.get("context") or "").casefold()
            if context and context not in result:
                result[context] = row
        return result

    @staticmethod
    def _latest(rows: Iterable[dict[str, Any]], timestamp: str) -> dict[str, Any]:
        candidates = list(rows)
        if not candidates:
            raise GitHubError("no matching authoritative publication was found")
        candidates.sort(
            key=lambda row: (
                str(row.get(timestamp) or row.get("created_at") or ""),
                int(row.get("id") or 0),
            ),
            reverse=True,
        )
        return candidates[0]

    def ci_manifest(self, number: int, sha: str) -> tuple[dict[str, Any], dict[str, Any]]:
        sha = normalize_sha(sha)
        matches: list[dict[str, Any]] = []
        for row in self.comments(number):
            body = str(row.get("body") or "")
            markers = _CI_MARKER_RE.findall(body)
            if not any(int(pr) == number and head.lower() == sha for pr, head, _ in markers):
                continue
            matches.append(row)
        row = self._latest(matches, "created_at")
        body = str(row.get("body") or "")
        fenced = re.search(r"```json\s*\n(.*?)\n```", body, re.DOTALL)
        if not fenced:
            raise GitHubError("latest exact-head CI comment has no JSON manifest fence")
        try:
            manifest = json.loads(fenced.group(1))
        except json.JSONDecodeError as exc:
            raise GitHubError(f"latest exact-head CI manifest is invalid JSON: {exc}") from exc
        if not isinstance(manifest, dict):
            raise GitHubError("latest exact-head CI manifest is not an object")
        if str(manifest.get("head_sha") or "").lower() != sha:
            raise GitHubError("latest CI manifest does not record the exact requested head")
        if str(manifest.get("pr") or "") != str(number) or manifest.get("partial"):
            raise GitHubError("latest CI manifest has the wrong PR or is partial")
        steps = manifest.get("steps")
        if not isinstance(steps, list):
            raise GitHubError("latest CI manifest has no step list")
        names = {str(step.get("step") or "") for step in steps if isinstance(step, dict)}
        if names != set(CANONICAL_CI_STEPS):
            raise GitHubError("latest CI manifest does not contain exactly the canonical steps")
        return row, manifest

    def review_ledger(self, number: int, sha: str) -> dict[str, Any]:
        sha = normalize_sha(sha)
        matches: list[dict[str, Any]] = []
        for row in self.reviews(number):
            body = str(row.get("body") or "")
            markers = _REVIEW_MARKER_RE.findall(body)
            if not any(int(pr) == number and head.lower() == sha for pr, head, _ in markers):
                continue
            if str(row.get("commit_id") or "").lower() != sha:
                raise GitHubError("review ledger marker is bound to a different commit")
            matches.append(row)
        row = self._latest(matches, "submitted_at")
        body = str(row.get("body") or "")
        if body.count("<!-- mipstarre:review-ledger ") != 1:
            raise GitHubError("latest exact-head review ledger has ambiguous markers")
        return row

    def post_status(self, sha: str, context: str, state: str, description: str) -> None:
        sha = normalize_sha(sha)
        context = context.strip()
        if not context or any(ord(ch) < 32 for ch in context):
            raise GitHubError("commit status context must be nonempty and printable")
        if state not in {"pending", "success", "failure", "error"}:
            raise GitHubError(f"invalid commit status state {state!r}")
        digest = stable_digest(
            {
                "sha": sha,
                "context": context.casefold(),
                "state": state,
                "description": description,
            },
            length=16,
        )
        suffix = f" [mip:{digest}]"
        rendered_description = description[: 140 - len(suffix)].rstrip() + suffix

        def lookup() -> dict[str, Any] | None:
            for row in self.statuses(sha):
                row_sha = str(row.get("sha") or "")
                if not _SHA_RE.fullmatch(row_sha) or row_sha.lower() != sha:
                    continue
                if str(row.get("context") or "").casefold() != context.casefold():
                    continue
                if str(row.get("state") or "").casefold() != state:
                    continue
                if str(row.get("description") or "") == rendered_description:
                    return row
            return None

